// @vitest-environment jsdom
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	fireEvent,
	render as rtlRender,
	screen,
	waitFor,
} from "@testing-library/react";
import type { ReactElement } from "react";
import { beforeEach, describe, expect, it, vi } from "vitest";

function render(ui: ReactElement) {
	const client = new QueryClient({
		defaultOptions: { queries: { retry: false } },
	});
	const wrap = (node: ReactElement) => (
		<QueryClientProvider client={client}>{node}</QueryClientProvider>
	);
	const result = rtlRender(wrap(ui));
	return {
		...result,
		rerender: (node: ReactElement) => result.rerender(wrap(node)),
	};
}

vi.mock("@/components/ui/code-editor", () => ({ CodeEditor: () => null }));
vi.mock("@tanstack/react-router", () => ({
	Link: ({
		children,
		params,
	}: {
		children: React.ReactNode;
		params?: Record<string, string>;
	}) => (
		<a href={`/${params?.owner}/agents/${params?.agentId}/skills`}>
			{children}
		</a>
	),
}));
vi.mock("@/hooks/use-features", () => ({
	useFeatures: () => ({ lobuEmbedded: false }),
}));

/** The owning agent's skill library — the bodies the compile draws from. */
const SKILLS = [
	{
		repo: "custom/triage",
		name: "triage",
		description: "Sort inbound",
		content: "Triage body.",
		enabled: true,
	},
	{
		repo: "custom/digest",
		name: "digest",
		description: "Summarize",
		content: "Digest body.",
		enabled: true,
	},
	{
		repo: "custom/off",
		name: "off",
		content: "Disabled body.",
		enabled: false,
	},
];

let emptyLibrary = false;
vi.mock("@/lib/api/agents", () => ({
	useAgents: () => ({ data: [{ agent_id: "ada", name: "Ada" }] }),
	useAgentConfig: () => ({
		data: { skillsConfig: { skills: emptyLibrary ? [] : SKILLS } },
	}),
	useAgentSkillsCatalog: () => ({ data: { catalog: [], installedSkills: [] } }),
}));

beforeEach(() => {
	emptyLibrary = false;
});
vi.mock("@/lib/api", () => ({
	useConnectedClients: () => ({ data: [] }),
	useEntities: () => ({ data: [] }),
}));
vi.mock("@/lib/api/entities", () => ({ useEntityTypes: () => ({ data: [] }) }));
vi.mock("@/lib/api/references", () => ({
	useReferenceSearch: () => ({ refs: [], isLoading: false }),
}));
vi.mock("@/hooks/use-org-context", () => ({
	useOrgContext: () => ({ currentOwner: "acme", resolvedOrganizationId: "o1" }),
}));

import { FromScratchPanel } from "./from-scratch-panel";

const SCHEDULE = [{ kind: "schedule" }];
const EVENT_TURN = [{ kind: "event", execution: "turn" }];

const baseProps = {
	organizationId: "org-1",
	onSubmit: vi.fn(),
	isSubmitting: false,
	error: null,
	prefill: { agent_id: "ada" },
};

function fillName(value = "Morning digest") {
	fireEvent.change(screen.getByPlaceholderText("e.g., Escalation signals"), {
		target: { value },
	});
}

function submitButton() {
	return screen.getByRole("button", { name: /Create Behavior|Save/ });
}

/** A skill chip exactly as the composer serializes it into the prompt. */
const chip = (name: string) =>
	`@[skill:${name}:${name}](/acme/agents/ada/skills)`;

describe("FromScratchPanel layout", () => {
	it("offers one instruction field, before the trigger fields", () => {
		render(
			<FromScratchPanel
				{...baseProps}
				triggers={SCHEDULE}
				triggerFields={<div data-testid="trigger-fields">trigger</div>}
			/>,
		);

		// The ordered skill picker is gone: skills are referenced inline instead,
		// so there is no separate control that also mutates the pinned set.
		expect(screen.queryByRole("button", { name: /Add a skill/ })).toBeNull();

		const name = screen.getByPlaceholderText("e.g., Escalation signals");
		const instructions = screen.getByText("Instructions");
		const trigger = screen.getByTestId("trigger-fields");
		expect(
			name.compareDocumentPosition(instructions) &
				Node.DOCUMENT_POSITION_FOLLOWING,
		).toBeTruthy();
		expect(
			instructions.compareDocumentPosition(trigger) &
				Node.DOCUMENT_POSITION_FOLLOWING,
		).toBeTruthy();
	});

	it("sends an author with an empty library to the agent's skills page", () => {
		// Regression from the picker era: the first live run hit an agent with no
		// skills and nothing on screen said where to get one. Still worth saying,
		// even though a prompt alone is now enough to save.
		emptyLibrary = true;
		render(<FromScratchPanel {...baseProps} triggers={SCHEDULE} />);
		const link = screen.getByRole("link", { name: /Add one/ });
		expect(link.getAttribute("href")).toBe("/acme/agents/ada/skills");
	});
});

describe("FromScratchPanel skill pinning", () => {
	it("sends the prompt and the bodies its chips resolve to", async () => {
		const onSubmit = vi.fn();
		render(
			<FromScratchPanel
				{...baseProps}
				prefill={{
					agent_id: "ada",
					prompt: `Do ${chip("digest")} then ${chip("triage")}`,
				}}
				onSubmit={onSubmit}
				triggers={SCHEDULE}
			/>,
		);

		fillName();
		fireEvent.click(submitButton());

		await waitFor(() => expect(onSubmit).toHaveBeenCalled());
		const payload = onSubmit.mock.calls[0][0];
		// The prompt keeps its chips — nothing strips ref tokens — and the bodies
		// ride alongside as snapshots. Both halves, from the one field.
		expect(payload.prompt).toContain("@[skill:digest:");
		expect(payload.skills).toEqual([
			{ name: "digest", content: "Digest body." },
			{ name: "triage", content: "Triage body." },
		]);
	});

	it("pins nothing when the prompt is plain prose", async () => {
		const onSubmit = vi.fn();
		render(
			<FromScratchPanel
				{...baseProps}
				prefill={{ agent_id: "ada", prompt: "Summarize yesterday." }}
				onSubmit={onSubmit}
				triggers={SCHEDULE}
			/>,
		);

		fillName();
		fireEvent.click(submitButton());

		await waitFor(() => expect(onSubmit).toHaveBeenCalled());
		expect(onSubmit.mock.calls[0][0].skills).toEqual([]);
	});

	it("blocks a chip whose skill is disabled in the library", () => {
		render(
			<FromScratchPanel
				{...baseProps}
				prefill={{ agent_id: "ada", prompt: chip("off") }}
				triggers={SCHEDULE}
			/>,
		);
		fillName();
		expect(screen.getByText(/disabled/i)).toBeTruthy();
		expect(submitButton()).toBeDisabled();
	});

	it("says when a pinned skill has newer text, without changing it", () => {
		// The whole point of storing snapshots: the drift is visible instead of
		// being applied silently under the author.
		render(
		render(
			<FromScratchPanel
				{...baseProps}
				prefill={{
					agent_id: "ada",
					prompt: chip("triage"),
					skills: [{ name: "triage", content: "Triage body v1." }],
				}}
				triggers={SCHEDULE}
			/>,
		);
		expect(
			screen.getByText(/has been edited since this Behavior pinned it/i),
		).toBeTruthy();
	});
});

describe("FromScratchPanel instruction requirement", () => {
	it("blocks a schedule Behavior with no instructions at all", () => {
		render(<FromScratchPanel {...baseProps} triggers={SCHEDULE} />);
		fillName();
		expect(
			screen.getByText(/Write what this Behavior should do/i),
		).toBeTruthy();
		expect(submitButton()).toBeDisabled();
	});

	it("accepts a chip alone — the pinned body IS the instruction", () => {
		render(
			<FromScratchPanel
				{...baseProps}
				prefill={{ agent_id: "ada", prompt: chip("triage") }}
				triggers={SCHEDULE}
			/>,
		);
		fillName();
		expect(
			screen.queryByText(/Write what this Behavior should do/i),
		).toBeNull();
		expect(submitButton()).not.toBeDisabled();
	});

	it("accepts prose alone, with no skill mentioned", () => {
		render(
			<FromScratchPanel
				{...baseProps}
				prefill={{ agent_id: "ada", prompt: "Summarize yesterday." }}
				triggers={SCHEDULE}
			/>,
		);
		fillName();
		expect(submitButton()).not.toBeDisabled();
	});

	it("lets an event-turn Behavior save with nothing", () => {
		render(<FromScratchPanel {...baseProps} triggers={EVENT_TURN} />);
		fillName();
		expect(submitButton()).not.toBeDisabled();
	});
});

describe("FromScratchPanel sources", () => {
	it("sends stored sources back explicitly so a save cannot drop them", async () => {
		const onSubmit = vi.fn();
		const sources = [{ name: "alpha", query: "@feed:12" }];
		render(
