type OutputConfigMode = "fields" | "json";
type OutputKind = "entity" | "event";
type OutputFieldRole = "plain" | "key" | "searchable";
type PermissionMode =
	| "acceptEdits"
	| "auto"
	| "bypassPermissions"
	| "default"
	| "dontAsk"
	| "plan";
type Effort = "low" | "medium" | "high";

interface OutputFieldDraft {
		: "";
}

function parseOptionalNumber(
	value: string,
	label: string,
): { value?: number; error?: string } {
	const trimmed = value.trim();
	if (!trimmed) return {};
	const parsed = Number(trimmed);
	if (!Number.isFinite(parsed)) return { error: `${label} must be a number.` };
	return { value: parsed };
}

function buildOutputConfigs({
	kind,
	entityType,
	eventType,
	outputName,
	fields,
}: {
	kind: OutputKind;
	entityType: string;
	eventType: string;
	outputName: string;
	fields: OutputFieldDraft[];
}): {
	classifiers?: unknown[];
	outputs?: Record<string, unknown>;
	error?: string;
} {
	const activeFields = fields
		.map((field) => ({ ...field, name: outputFieldSlug(field.name) }))
		.filter((field) => field.name);
	const keyFields = activeFields
		.filter((field) => field.role === "key")
		.map((field) => field.name);
	const searchableFields = activeFields.filter(
		(field) => field.role === "searchable",
	);
	const trimmedEntityType = entityTypeSlug(entityType);
	const trimmedEventType = eventType.trim();
	const trimmedOutputName = outputFieldSlug(outputName);
	const hasOutput =
		kind === "event" ? trimmedEventType.length > 0 : keyFields.length > 0;

	if (hasOutput && !trimmedOutputName) {
		return { error: "Output name is required." };
	}
	if (kind === "event") {
		return {
			outputs: hasOutput
				? { [trimmedOutputName]: { event: trimmedEventType } }
				: undefined,
		};
	}
	if (
		(trimmedEntityType || activeFields.length > 0) &&
		keyFields.length === 0
	) {
		return { error: "Entity outputs need at least one Key field." };
	}

	if (keyFields.length > 0 && !trimmedEntityType) {
		return { error: "Key fields need an output entity type." };
	}

	if (searchableFields.length > 0 && !trimmedOutputName) {
		return { error: "Output name is required." };
	}

	return {
		outputs:
			keyFields.length > 0
				? {
						[trimmedOutputName]: {
							entity: trimmedEntityType,
							key: keyFields,
						},
					}
				: undefined,
		classifiers:
			searchableFields.length > 0
				? searchableFields.map((field) => ({
						slug: field.name,
						name: labelFromFieldName(field.name),
						source_path: `$.${trimmedOutputName}[*]`,
						value_field: field.name,
					}))
				: undefined,
	};

	const instructionsRequired = behaviorRequiresInstructions(triggers);
	const skillsError = validateBehaviorPrompt(prompt, skillLibrary, triggers);

	// Both halves of the write, derived from the one field. The server rejects
	// them if they disagree (`assertPromptSkillTokensPinned`), so resolving here
	// from the same prompt string is what keeps them honest.
	const pinnedForSave = resolveSkillSnapshots(prompt, skillLibrary);

	const canSubmit = Boolean(name.trim()) && !skillsError;

	const handleSubmit = () => {
		if (!canSubmit) return;

		let classifiers: unknown[] | undefined;
		let outputs: Record<string, unknown> | undefined;
		if (outputConfigMode === "fields") {
			const generated = buildOutputConfigs({
				kind: outputKind,
				entityType: outputEntityType,
				eventType: outputEventType,
				outputName,
				fields: outputFields,
			});
			if (generated.error) {
				setOutputsError(generated.error);
				return;
			}
			classifiers = generated.classifiers;
			outputs = generated.outputs;
			setClassifiersError(null);
			setOutputsError(null);
		} else {
			if (classifiersText.trim()) {
				try {
					const parsed = JSON.parse(classifiersText);
					if (!Array.isArray(parsed)) {
						setClassifiersError("Classifiers must be a JSON array.");
						return;
					}
					classifiers = parsed;
				} catch {
					setClassifiersError("Invalid JSON. Please check the syntax.");
					return;
				}
			}
			setClassifiersError(null);

			if (outputsText.trim()) {
				try {
					const parsed = JSON.parse(outputsText);
					if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
						setOutputsError("Outputs must be a JSON object.");
						return;
					}
					outputs = parsed;
				} catch {
					setOutputsError("Invalid JSON. Please check the syntax.");
					return;
				}
			}
			setOutputsError(null);
		}
		if (
			outputs &&
			Object.keys(outputs).length > 0 &&
			(triggers ?? []).some(
				(trigger) =>
					trigger.kind === "event" && (trigger.execution ?? "turn") === "turn",
			)
		) {
			setOutputsError(
				"Outputs require window execution. Change the event trigger or split the conversational turn into another Behavior.",
			);
			return;
		}

		const timeout = parseOptionalNumber(timeoutSeconds, "Timeout");
		if (timeout.error) {
			setExecutionConfigError(timeout.error);
			return;
		}
		if (
			timeout.value !== undefined &&
			(!Number.isInteger(timeout.value) || timeout.value < 1)
		) {
			setExecutionConfigError("Timeout must be a whole number greater than 0.");
			return;
		}
		const budget = parseOptionalNumber(maxBudgetUsd, "Budget");
		if (budget.error) {
			setExecutionConfigError(budget.error);
			return;
		}
		if (budget.value !== undefined && budget.value < 0) {
			setExecutionConfigError("Budget cannot be negative.");
			return;
		}
		const nudges = parseOptionalNumber(finalizeNudges, "Finalize nudges");
		if (nudges.error) {
			setExecutionConfigError(nudges.error);
			return;
		}
		if (
			nudges.value !== undefined &&
			(!Number.isInteger(nudges.value) || nudges.value < 0 || nudges.value > 5)
		) {
			setExecutionConfigError(
				"Finalize nudges must be a whole number from 0 to 5.",
			);
			return;
		}
		const executionEntries = {
			...(timeout.value !== undefined
				? { timeout_seconds: timeout.value }
				: {}),
			...(budget.value !== undefined ? { max_budget_usd: budget.value } : {}),
			...(runModel.trim() ? { model: runModel.trim() } : {}),
			...(permissionMode ? { permission_mode: permissionMode } : {}),
			...(effort ? { effort } : {}),
			...(nudges.value !== undefined ? { finalize_nudges: nudges.value } : {}),
		};
		const executionConfig =
			Object.keys(executionEntries).length > 0
				? (executionEntries as Record<string, unknown>)
				: undefined;
		setExecutionConfigError(null);

		const tags = tagsText.trim()
			? tagsText
					.split(",")
					.map((t) => t.trim())
					.filter(Boolean)
			: undefined;

		onSubmit({
			slug: displaySlug,
			name: name.trim(),
			description: description.trim() || undefined,
			prompt,
			skills: pinnedForSave,
			entity_id: selectedEntityId,
			scheduler_client_id: schedulerClientId.trim() || undefined,
			sources,
			reaction_script: reactionScript.trim() || undefined,
			classifiers,
			outputs,
			reactions_guidance: reactionsGuidance.trim() || undefined,
			execution_config: executionConfig,
			tags,
			change_notes: changeNotes.trim() || undefined,
			agent_id: agentId.trim() || undefined,
		});
	};

	return (
		<div className="space-y-4">
			<div className="space-y-4">
				<div className="space-y-2">
					<div className="flex items-center justify-between gap-3">
						<Label htmlFor="scratch-name">

