type CatalogPrefill = NonNullable<CreateBehaviorFormProps["catalogPrefill"]>;

function templateToPrefill(template: BehaviorCatalogTemplate): CatalogPrefill {
	const detail = template.detail ?? {};
	return {
		name: template.name,
		slug: detail.slug,
		description: detail.description ?? template.description ?? undefined,
		prompt: detail.prompt,
		triggers: detail.triggers,
		sources: detail.sources,
		classifiers: detail.classifiers,
		outputs: detail.outputs,
		reactions_guidance: detail.reactions_guidance,
		reaction_script: detail.reaction_script,
		model_config: detail.model_config,
		execution_config: detail.execution_config,
		tags: detail.tags,
	};
}

export function CreateBehaviorForm({
	onClose,
	hideCancel = false,
	hideHeader = false,
	organizationId,
	entityId,
	entityName,
	prefillAgentId,
	onSuccess,
	editingBehavior,
	initialMode = "template",
	catalogPrefill,
	onDraft,
	triggerFields,
	submitLabel,
	submitDisabled,
	createFields,
}: CreateBehaviorFormProps) {
	const createBehavior = useCreateBehavior();
	const createVersion = useCreateBehaviorVersion();
	const setReactionScript = useSetReactionScript();
	const updateBehavior = useUpdateBehavior();
	const isEditing = !!editingBehavior;
	const [mode, setMode] = useState<CreationMode>(initialMode);
	const [clonePrefill, setClonePrefill] = useState<
		| {
				name?: string;
				slug?: string;
				prompt?: string;
				classifiers?: unknown[];
				outputs?: Record<string, unknown>;
		  }
		| undefined
	>(undefined);
	// A template picked from the "From templates" tab, folded into the scratch form.
	const [templatePrefill, setTemplatePrefill] = useState<
		CatalogPrefill | undefined
	>(undefined);

	const { data: templates = [], isLoading: templatesLoading } =
		useBehaviorCatalog();
	const [templateSearch, setTemplateSearch] = useState("");
	const agentPrefill = useMemo(
		() => (prefillAgentId ? { agent_id: prefillAgentId } : undefined),
		[prefillAgentId],
	);
	const templateItems = useMemo(
		() =>
			templates.map((t) => ({
				key: t.id,
				name: t.name,
				description: t.description ?? "",
				badges: t.detail?.tags ?? [],
			})),
		[templates],
	);
	const filteredTemplates = useMemo(
		() =>
			templateItems.filter(
				(item) =>
					item.name.toLowerCase().includes(templateSearch.toLowerCase()) ||
					item.description.toLowerCase().includes(templateSearch.toLowerCase()),
			),
		[templateItems, templateSearch],
	);
	const handleSelectTemplate = (item: CatalogPickerItem) => {
		const template = templates.find((t) => t.id === item.key);
		if (!template) return;
		const prefill = templateToPrefill(template);
		// catalogPrefill precedence folds the agent in to keep the agent-scoped
		// create context when a template is chosen.
		setTemplatePrefill(
			prefillAgentId ? { ...prefill, agent_id: prefillAgentId } : prefill,
		: (createFields?.triggers ??
			templatePrefill?.triggers ??
			catalogPrefill?.triggers ??
			[]);

	const handleCreate = async (params: BehaviorFormDraft) => {
		try {
			if (onDraft) {
				await onDraft(params);
				return;
			}
			if (isEditing) {
				const triggers =
					createFields?.triggers ?? editingBehavior.triggers ?? [];
				// Single atomic create_version call — also updates Behavior-level fields.
				await createVersion.mutateAsync({
					behavior_id: editingBehavior.behavior_id,
					name: params.name,
					description: params.description,
					prompt: params.prompt,
					sources: params.sources,
					set_as_current: true,
					triggers,
					scheduler_client_id: params.scheduler_client_id || null,
					classifiers: params.classifiers,
					outputs: params.outputs,
					reactions_guidance: params.reactions_guidance,
					change_notes: params.change_notes,
				});
				// Reaction script is compiled server-side, so it's a separate call
				const originalScript = editingBehavior.reaction_script ?? "";
				const newScript = params.reaction_script ?? "";
				if (newScript !== originalScript) {
					await setReactionScript.mutateAsync({
						behavior_id: editingBehavior.behavior_id,
						reaction_script: newScript,
					});
				}
				// Behavior-level fields (not part of version).
				const behaviorUpdates: Record<string, unknown> = {};
				if (params.model_config !== undefined)
					behaviorUpdates.model_config = params.model_config;
				if (params.execution_config !== undefined)
					behaviorUpdates.execution_config = params.execution_config;
				if (params.tags !== undefined) behaviorUpdates.tags = params.tags;
				if (params.agent_id !== undefined)
					behaviorUpdates.agent_id = params.agent_id || null;
				if (Object.keys(behaviorUpdates).length > 0) {
					await updateBehavior.mutateAsync({
						behavior_id: editingBehavior.behavior_id,
						...behaviorUpdates,
					});
				}
				handleClose();
				onSuccess?.(editingBehavior.behavior_id);
			} else {
				const initialTriggers =
					createFields?.triggers ??
					templatePrefill?.triggers ??
					catalogPrefill?.triggers ??
					[];
				const result = await createBehavior.mutateAsync({
					...params,
					triggers: initialTriggers,
				});
				handleClose();
				if (result.behavior_id) {
					onSuccess?.(result.behavior_id);
				}
			}
		} catch {
			// error is shown by the panel
		}
	};

	const mutationState = isEditing ? createVersion : createBehavior;
	let description = "Add a behavior";
	if (isEditing) {
		description = "Edit behavior configuration (saves as a new version)";
	} else if (entityName) {
		description = `Add a behavior for ${entityName}`;
	}

	const editPrefill = editingBehavior
		? {
				entity_id: editingBehavior.entity_id,
				name: editingBehavior.name,
				slug: editingBehavior.slug,
				description: editingBehavior.description,
				prompt: editingBehavior.prompt,
				sources: editingBehavior.sources,
				reaction_script: editingBehavior.reaction_script,
				scheduler_client_id: editingBehavior.scheduler_client_id ?? undefined,
				classifiers: editingBehavior.classifiers,
				outputs: editingBehavior.outputs,
				reactions_guidance: editingBehavior.reactions_guidance,
				model_config: editingBehavior.model_config,
				execution_config: editingBehavior.execution_config,
				tags: editingBehavior.tags,
				agent_id: editingBehavior.agent_id ?? undefined,
			}
		: undefined;

	const titleText = isEditing ? "Edit Behavior" : "Create Behavior";

