			set_as_current?: boolean;
			change_notes?: string;
			// Behavior-level fields (applied atomically with the version)
			scheduler_client_id?: string | null;
			triggers?: Array<Record<string, unknown>>;
			classifiers?: unknown[];
			outputs?: Record<string, unknown>;
			reactions_guidance?: string;
		}) => {
			return apiCall<{
				behavior_id: string;
				version: number;
				version_id: string;
				previous_version: number;
			}>("manage_behaviors", {
				action: "create_version",
				...params,
			});
		},
		onSuccess: () => {
			queryClient.invalidateQueries({ queryKey: ["behaviors-list"] });
			queryClient.invalidateQueries({ queryKey: ["behavior-detail"] });
			queryClient.invalidateQueries({ queryKey: ["behaviors"] });
		},
	});
}

