import { describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
	createBehavior: vi.fn(),
	fromScratchPrefill: vi.fn(),
	fromScratchTriggers: vi.fn(),
	setReactionScript: vi.fn(),
}));

vi.mock("@/components/agents/catalog-picker", () => ({
	CatalogPicker: ({
		onSelect,
	}: {
		onSelect: (item: {
			key: string;
			name: string;
			description: string;
		}) => void;
	}) => (
		<button
			type="button"
			onClick={() =>
				onSelect({ key: "template-1", name: "Template", description: "" })
			}
		>
			Use template
