	FromScratchPanel: ({
		prefill,
		onSubmit,
		triggers,
	}: {
		prefill?: {
			name?: string;
			prompt?: string;
			reaction_script?: string;
		};
		onSubmit: (params: {
			slug: string;
			name: string;
			prompt: string;
			reaction_script?: string;
		}) => void;
		triggers?: Array<Record<string, unknown>>;
	}) => {
		mocks.fromScratchPrefill(prefill);
		mocks.fromScratchTriggers(triggers);
		return (
			<button
				type="button"
				onClick={() =>
					onSubmit({
						slug: "template",
						name: prefill?.name ?? "Template",
						prompt: prefill?.prompt ?? "Analyze events",
						reaction_script: prefill?.reaction_script,
					})
				}
			>
				Create Behavior
			</button>
		);
	},
}));

vi.mock("@/hooks/use-behaviors", () => ({
	useCreateBehavior: () => ({
		mutateAsync: mocks.createBehavior,
		reset: vi.fn(),
		isPending: false,
		error: null,
	}),
	useCreateBehaviorVersion: () => ({
		mutateAsync: vi.fn(),
		reset: vi.fn(),
		isPending: false,
		error: null,
	}),
	useSetReactionScript: () => ({
		mutateAsync: mocks.setReactionScript,
		reset: vi.fn(),
		isPending: false,
		error: null,
	}),
	useUpdateBehavior: () => ({ mutateAsync: vi.fn() }),
	useBehaviorCatalog: () => ({
		data: [
			{
				id: "template-1",
				name: "Template",
				detail: {
					prompt: "Analyze events",
					triggers: [
						{
							kind: "schedule",
							cron: "0 8 * * *",
							execution: "window",
							active_run: "coalesce",
							skip_if_unchanged: true,
						},
					],
					reaction_script: "export default async function reaction() {}",
				},
			},
		],
		isLoading: false,
	}),
	useBehaviorsList: () => ({ data: [], isLoading: false }),
}));

import { CreateBehaviorForm } from "./create-behavior-form";

describe("CreateBehaviorForm", () => {
	it("forwards the composed triggers without churning an agent-only prefill", () => {
		const props = {
			onClose: vi.fn(),
			organizationId: "org-1",
			prefillAgentId: "agent-1",
			initialMode: "scratch" as const,
		};
		const first = [{ kind: "event", execution: "turn" }];
		const second = [{ kind: "schedule", cron: "0 9 * * *" }];
		const { rerender } = render(
			<CreateBehaviorForm {...props} createFields={{ triggers: first }} />,
		);
		const firstPrefill = mocks.fromScratchPrefill.mock.lastCall?.[0];
		expect(mocks.fromScratchTriggers).toHaveBeenLastCalledWith(first);

		rerender(
			<CreateBehaviorForm {...props} createFields={{ triggers: second }} />,
		);

		// The panel decides whether skills are required from these triggers, so a
