	const keyFields = activeFields
		.filter((field) => field.role === "key")
		.map((field) => field.name);
	const searchableFields = activeFields.filter(
		(field) => field.role === "searchable",
	);
	const trimmedEntityType = entityTypeSlug(entityType);
	const trimmedEventType = eventType.trim();
	const trimmedOutputName = outputFieldSlug(outputName);
	const hasOutput =
		kind === "event" ? trimmedEventType.length > 0 : keyFields.length > 0;

	if (hasOutput && !trimmedOutputName) {
		return { error: "Output name is required." };
	}
	if (kind === "event") {
		return {
			outputs: hasOutput
				? { [trimmedOutputName]: { event: trimmedEventType } }
				: undefined,
		};
	}
	if (
