];
const EFFORT_LEVELS: Array<{ value: Effort; label: string }> = [
	{ value: "low", label: "Low" },
	{ value: "medium", label: "Medium" },
	{ value: "high", label: "High" },
];

let outputFieldDraftCounter = 0;

function nextOutputFieldDraftId(): string {
	outputFieldDraftCounter += 1;
	return `field-${outputFieldDraftCounter}`;
}

function createOutputFieldDraft(
	partial: Partial<OutputFieldDraft> = {},
): OutputFieldDraft {
	return {
		id: nextOutputFieldDraftId(),
		name: partial.name ?? "",
		type: partial.type ?? "text",
		role: partial.role ?? "plain",
	};
}

function labelFromFieldName(name: string): string {
	return name
		.replace(/[_-]+/g, " ")
		.replace(/\s+/g, " ")
		.trim()
		.replace(/\b\w/g, (char) => char.toUpperCase());
}

function outputFieldSlug(value: string): string {
	return value
		.trim()
		.toLowerCase()
		.replace(/[^a-z0-9_]+/g, "_")
		.replace(/^_+|_+$/g, "");
}

function entityTypeSlug(value: string): string {
	return value
		.trim()
		.toLowerCase()
		.replace(/[^a-z0-9_-]+/g, "-")
		.replace(/^[-_]+|[-_]+$/g, "");
}

function guidedOutput(
	outputs?: Record<string, unknown>,
): { name: string; kind: OutputKind; config: Record<string, unknown> } | null {
	if (!outputs) return null;
	const entries = Object.entries(outputs);
	if (entries.length !== 1) return null;
	const [name, value] = entries[0];
	if (!value || typeof value !== "object" || Array.isArray(value)) return null;
	const config = value as Record<string, unknown>;
	if (
		typeof config.entity === "string" &&
		Array.isArray(config.key) &&
		Object.keys(config).every((key) => ["entity", "key", "name"].includes(key))
	) {
		return { name, kind: "entity", config };
	}
	if (
		typeof config.event === "string" &&
		Object.keys(config).every((key) => key === "event")
	) {
		return { name, kind: "event", config };
	}
	return null;
}

function outputsCanUseFields(outputs?: Record<string, unknown>): boolean {
	return !outputs || guidedOutput(outputs) !== null;
