  metadata?: Record<string, unknown>;
  author?: string;
  source_url?: string;
  occurred_at?: string;
  parent_event_id?: number;
  payload_type?: 'text' | 'markdown';
  idempotency_key?: string;
}

export interface PersistBehaviorEventOutputParams {
  tx: DbClient;
  rows: unknown;
  outputName: string;
  output: EventOutput;
  watcherId: number;
  organizationId: string;
  windowId: number;
  canvasRevisionId: number;
  runId: number | null;
  boundEntityIds: number[];
  validContentIds: Set<number>;
  occurredAt: string;
  createdBy?: string | null;
}

async function findByIdempotencyKey(
  tx: DbClient,
  organizationId: string,
  idempotencyKey: string
): Promise<InsertedEvent | null> {
  const rows = await tx<InsertedEvent>`
    SELECT id, entity_ids, origin_id, title, semantic_type, created_at,
           'unchanged'::text AS change
    FROM events
    WHERE organization_id = ${organizationId}
      AND metadata ? '_lobu_idempotency_key'
      AND metadata->>'_lobu_idempotency_key' = ${idempotencyKey}
    LIMIT 1
  `;
  return rows[0] ?? null;
}

/** Persist one declared event array atomically with its Canvas window. */
export async function persistBehaviorEventOutput(
  params: PersistBehaviorEventOutputParams
): Promise<InsertedEvent[]> {
  if (!Array.isArray(params.rows) || params.rows.length === 0) return [];
  const seenIdempotencyKeys = new Set<string>();
  for (let index = 0; index < params.rows.length; index++) {
    const draft = params.rows[index] as EventDraft;
    if (typeof draft?.idempotency_key !== 'string') continue;
    if (seenIdempotencyKeys.has(draft.idempotency_key)) {
      throw new ToolUserError(
        `outputs.${params.outputName} contains a duplicate idempotency_key at item ${index}.`,
        422
      );
    }
    seenIdempotencyKeys.add(draft.idempotency_key);
  }
  const inserted: InsertedEvent[] = [];
  const producer = `canvas:${params.canvasRevisionId}`;

  for (let index = 0; index < params.rows.length; index++) {
    const draft = params.rows[index] as EventDraft;
    const metadata = { ...(draft.metadata ?? {}) };
    delete metadata._lobu_idempotency_key;

    const kindValidation = await validateSaveContentSemanticType(
      params.output.event,
      metadata,
      params.organizationId,
      params.boundEntityIds.length > 0 ? params.boundEntityIds : undefined
    );
    if (!kindValidation.valid) {
      throw new ToolUserError(
        `Invalid event in outputs.${params.outputName}[${index}]: ${kindValidation.errors.join('\n')}`,
        422
      );
    }

    let parentOriginId: string | null = null;
    let parentSourceUrl: string | null = null;
    if (draft.parent_event_id != null) {
      if (!params.validContentIds.has(draft.parent_event_id)) {
        throw new ToolUserError(
          `outputs.${params.outputName}[${index}].parent_event_id must reference content read by this Behavior window.`,
          422
        );
      }
      const parentRows = await params.tx<{ origin_id: string; source_url: string | null }>`
        SELECT origin_id, source_url
        FROM events
        WHERE id = ${draft.parent_event_id}
          AND organization_id = ${params.organizationId}
        LIMIT 1
      `;
      if (parentRows.length === 0 || !parentRows[0].origin_id) {
        throw new ToolUserError(
          `outputs.${params.outputName}[${index}].parent_event_id does not resolve to a source event.`,
          422
        );
      }
      parentOriginId = parentRows[0].origin_id;
      parentSourceUrl = parentRows[0].source_url;
    }

    const idempotencyKey = draft.idempotency_key
      ? `behavior:${params.watcherId}:output:${params.outputName}:key:${draft.idempotency_key}`
      : `behavior:${params.watcherId}:${producer}:output:${params.outputName}:item:${index}`;
    const prior = await findByIdempotencyKey(
      params.tx,
      params.organizationId,
      idempotencyKey
    );
    if (prior) {
      if (prior.semantic_type !== params.output.event) {
        throw new ToolUserError(
          `Behavior output idempotency key already belongs to '${prior.semantic_type}'.`,
          409
        );
      }
      inserted.push(prior);
      continue;
    }

    const eventMetadata = {
      ...metadata,
      _lobu_idempotency_key: idempotencyKey,
      behavior_id: params.watcherId,
      behavior_output: params.outputName,
      window_id: params.windowId,
      window_revision_id: params.canvasRevisionId,
    };
    try {
      inserted.push(
        await params.tx.savepoint((sp) =>
          insertEvent(
            {
              entityIds: params.boundEntityIds,
              organizationId: params.organizationId,
    // concurrent supersedes race on idx_events_superseded_by → 23505 → 409.
    //
    // Any other same-period completion is an idempotent no-op that returns the
    // existing root — the agent loop can retry a period forever without
    // duplicating a root or overwriting a successful head (LOBU-Q); a genuine
    // re-analysis states replace_existing explicitly.
    // ============================================
    let windowId!: number;
    let canvasRevisionId!: number;
    let windowCreated = false;
    let headSuperseded = false;
    const canvasEntityId = await ensureCanvasEntity({
      tx,
      watcherId: Number(watcherId),
      organizationId: watcherOrgId,
      parentEntityId,
      createdBy: watcherCreatedBy,
    });
    const canvasEntityIds = canvasEntityId != null ? [canvasEntityId] : [];
    // events.client_id has an FK to oauth_clients — but callers pass PAT/device
    // ids verbatim (the legacy column had no FK, so they were accepted). Inside
    // this transaction insertEvent's client-id-FK retry cannot engage (the
    // first failed INSERT aborts the tx), so resolve validity up front and
    // drop unknown ids to NULL rather than aborting the whole completion.
    let canvasClientId: string | null = provenanceClientId;
    if (canvasClientId) {
      const knownClient = await tx`
        SELECT 1 FROM oauth_clients WHERE id = ${canvasClientId} LIMIT 1
      `;
      if (knownClient.length === 0) canvasClientId = null;
    }
    const canvasPeriodMeta = {
      watcher_id: Number(watcherId),
      granularity: timeGranularity,
      window_start,
      window_end,
      content_analyzed: batchContentIds.length,
      version_id: resolvedVersionId,
    };

    const existingHead = await findCanvasHead(tx, {
      watcherId: Number(watcherId),
      granularity: timeGranularity,
      windowStart: window_start,
    });

    if (existingHead && !args.replace_existing) {
      // Idempotent replay / concurrent completion that already produced a head:
      // never create a second root and never overwrite a successful head. The
      // window identity is the existing chain root.
      windowId = existingHead.rootEventId;
      canvasRevisionId = existingHead.id;
    } else if (existingHead && args.replace_existing) {
      // Supersede the current head, copying the root's period metadata. Loser of
      // a concurrent supersede hits idx_events_superseded_by → 23505 → 409. The
      // root id (window identity) never changes across a supersede.
      windowId = existingHead.rootEventId;
      try {
        const replacement = await insertEvent(
          {
            entityIds: canvasEntityIds,
            organizationId: watcherOrgId,
            originId: `canvas_${crypto.randomUUID()}`,
            payloadType: 'json_template',
            payloadData: cleanedExtractedData,
            semanticType: 'canvas_state',
            metadata: {
              ...canvasPeriodMeta,
              root_event_id: existingHead.rootEventId,
            },
            runId: watcherRunId,
            occurredAt: window_end,
            createdBy: watcherCreatedBy,
            clientId: canvasClientId,
            supersedesEventId: existingHead.id,
          },
          { sql: tx }
        );
        canvasRevisionId = Number(replacement.id);
      } catch (err) {
        if (isUniqueViolation(err, 'idx_events_superseded_by')) {
          throw new ToolUserError(
            `Canvas for Behavior ${watcherId} period ${window_start} was concurrently updated. Retry with the latest state.`,
            409
          );
        }
        throw err;
      }
      headSuperseded = true;
      if (args.replace_existing) {
        // An explicit replace states "this analysis covers THIS content set":
        // clear the previous completion's links so STEP 8 re-links exactly the
        // new batch.
        await tx`DELETE FROM watcher_window_events WHERE window_id = ${windowId}`;
      }
    } else {
      // No chain yet → insert the ROOT. A root omits metadata.root_event_id (its
      // id isn't known until after insert, and metadata is immutable); readers
      // treat a missing root_event_id as "self", so the root id IS the window id.
      // Superseders above stamp root_event_id explicitly for zero-traversal reads.
      try {
        const rootEvent = await insertEvent(
          {
            entityIds: canvasEntityIds,
            organizationId: watcherOrgId,
            originId: `canvas_${crypto.randomUUID()}`,
            payloadType: 'json_template',
            payloadData: cleanedExtractedData,
            semanticType: 'canvas_state',
            metadata: canvasPeriodMeta,
            runId: watcherRunId,
            occurredAt: window_end,
            createdBy: watcherCreatedBy,
            clientId: canvasClientId,
          },
          { sql: tx }
        );
        windowId = Number(rootEvent.id);
        canvasRevisionId = windowId;
        windowCreated = true;
        logger.info(
          `[complete_window] Created canvas window ${windowId} for watcher ${watcherId} (${window_start} - ${window_end})`
        );
      } catch (err) {
        if (isUniqueViolation(err, 'idx_canvas_chain_root')) {
          throw new ToolUserError(
            `Window already exists for Behavior ${watcherId} for period ${window_start} to ${window_end}. ` +
              'Use replace_existing: true to replace it, or query a different time period.',
            409
          );
        }
        throw err;
      }
    }

    // ============================================
    // STEP 8.5: Persist declared entity and event outputs atomically with Canvas.
    // ============================================
    const entityChanges = [] as Array<{
      entityId: number;
      name: string;
      kind: 'created' | 'updated';
      applied: Record<string, unknown>;
    }>;
    for (const [outputName, output] of Object.entries(outputs ?? {})) {
      if ('entity' in output) {
        const promote = await promoteBehaviorEntityOutput({
          tx,
          extractedData,
          outputName,
          output,
          watcherId: Number(watcherId),
          organizationId: watcherOrgId,
          windowId,
          parentEntityId,
          createdBy: watcherCreatedBy,
          validContentIds,
        });
        deferredApprovals.push(...promote.deferred);
        entityChanges.push(...promote.changes);
      } else {
        await persistBehaviorEventOutput({
          tx,
          rows: extractedData[outputName],
          outputName,
          output,
          watcherId: Number(watcherId),
          organizationId: watcherOrgId,
          windowId,
          canvasRevisionId,
          runId: watcherRunId,
          boundEntityIds,
          validContentIds,
          occurredAt: window_end,
          createdBy: watcherCreatedBy,
        });
      }
    expect(draft).toMatchObject({
      semantic_type: 'draft_reply',
      origin_parent_id: source.origin_id,
    });
    expect(observations.map((row) => Number(row.metadata.rank))).toEqual([1, 2]);

    // A source-derived idempotency key is intentionally stronger than a run
    // retry key: a later run that rediscovers the same post reuses the original
    // event instead of appending a duplicate.
    const laterRun = await createWatcherRun({
      organizationId: workspace.org.id,
      watcherId,
      agentId: agent.agentId,
      windowStart: pending.windowStart.toISOString(),
      windowEnd: pending.windowEnd.toISOString(),
      dispatchSource: 'scheduled',
    });
    const reused = await sql.begin(async (tx) =>
      persistBehaviorEventOutput({
        tx: tx as unknown as DbClient,
        rows: [extracted.observations[0]],
        outputName: 'observations',
        output: { event: 'observation' },
        watcherId,
        organizationId: workspace.org.id,
        windowId: firstCompletion.window_id,
        canvasRevisionId: firstCompletion.window_id,
        runId: laterRun.runId,
        boundEntityIds: [parent.id],
        validContentIds: new Set([source.id]),
        occurredAt: pending.windowEnd.toISOString(),
        createdBy: ownerUserId,
      })
    );
    expect(reused).toHaveLength(1);
    expect(reused[0].id).toBe(observations[0].id);

    await expect(
      sql.begin((tx) =>
        persistBehaviorEventOutput({
          tx: tx as unknown as DbClient,
          rows: [
            { content: 'First draft', idempotency_key: 'duplicate-in-one-output' },
            { content: 'Different draft', idempotency_key: 'duplicate-in-one-output' },
          ],
          outputName: 'drafts',
          output: { event: 'draft_reply' },
          watcherId,
          organizationId: workspace.org.id,
          windowId: firstCompletion.window_id,
          canvasRevisionId: firstCompletion.window_id,
          runId: laterRun.runId,
          boundEntityIds: [parent.id],
          validContentIds: new Set([source.id]),
          occurredAt: pending.windowEnd.toISOString(),
          createdBy: ownerUserId,
        })
      )
    ).rejects.toThrow(/duplicate.*idempotency/i);
  });

  it('appends changed unkeyed output for a Canvas replacement and deduplicates its retry', async () => {
    const sql = getTestDb();
    const workspace = await TestWorkspace.create({ name: 'Behavior Event Replacement Org' });
    const ownerUserId = workspace.users.owner.id;
    const parent = await createTestEntity({
      name: 'Observed account',
      organization_id: workspace.org.id,
      created_by: ownerUserId,
    });
    const agent = await createTestAgent({
      organizationId: workspace.org.id,
      ownerUserId,
      agentId: 'event-replacement-agent',
    });
    const api = await TestApiClient.for({
      organizationId: workspace.org.id,
      userId: ownerUserId,
      memberRole: 'owner',
    });
    const created = (await api.behaviors.create({
      entity_id: parent.id,
      slug: 'event-replacement-behavior',
      prompt: 'Return one observation.',
      triggers: [{ kind: 'schedule', cron: '0 9 * * *' }],
      outputs: { observations: { event: 'observation' } },
      agent_id: agent.agentId,
    })) as { behavior_id: string };
    const watcherId = Number(created.behavior_id);
    await sql`UPDATE watchers SET next_run_at = NOW() - INTERVAL '10 minutes' WHERE id = ${watcherId}`;

    const granularity = inferBehaviorGranularityFromSchedule('0 9 * * *');
    const pending = await computePendingWindow(sql as unknown as DbClient, watcherId, granularity);
    await createTestEvent({
      entity_id: parent.id,
      organization_id: workspace.org.id,
      content: 'A source event for this window.',
      occurred_at: new Date(pending.windowStart.getTime() + 60 * 60 * 1000),
    });
    const knowledge = (await api.knowledge.read({ behavior_id: watcherId })) as {
      window_token: string;
    };

    const first = (await api.behaviors.completeWindow({
      behavior_id: String(watcherId),
      window_token: knowledge.window_token,
      extracted_data: { observations: [{ content: 'First analysis.' }] },
    })) as { window_id: number };
    const replace = () =>
      api.behaviors.completeWindow({
        behavior_id: String(watcherId),
        window_token: knowledge.window_token,
        extracted_data: { observations: [{ content: 'Replacement analysis.' }] },
        replace_existing: true,
      });
    const replacement = (await replace()) as { window_id: number };
    expect(replacement.window_id).toBe(first.window_id);

    await api.behaviors.completeWindow({
      behavior_id: String(watcherId),
      window_token: knowledge.window_token,
      extracted_data: { observations: [{ content: 'Replacement analysis.' }] },
    });

    const outputs = await sql<{ content: string }>`
      SELECT payload_text AS content
      FROM events
      WHERE organization_id = ${workspace.org.id}
        AND metadata->>'behavior_output' = 'observations'
      ORDER BY id
    `;
    expect(outputs.map((row) => row.content)).toEqual([
      'First analysis.',
      'Replacement analysis.',
    ]);
  });
});
"}

