      ${sql.json(params.toolArgs)},
      ${params.toolResult ? sql.json(params.toolResult) : null},
      ${params.entityId ?? null},
      ${params.runId ?? null}
    )
  `.catch((err) => logger.error(err, 'Failed to track watcher reaction'));
}
