async function replayExistingOperationRun(
	claim: Awaited<ReturnType<typeof createConnectorOperationRun>>,
	operationName: string,
	ctx: ToolContext,
): Promise<ManageOperationsResult> {
	const sql = getDb();
	if (claim.approvalStatus === "pending" && claim.status === "pending") {
		const eventRows = await sql<{ id: number }>`
			SELECT id
			FROM events
			WHERE organization_id = ${ctx.organizationId}
			  AND run_id = ${claim.runId}
			  AND interaction_type = 'approval'
			ORDER BY id DESC
			LIMIT 1
		`;
		const { ownerSlug: orgSlug, baseUrl } = await getOrgUrlContext(ctx);
		const approvalUrl = buildResourcePermalink(
			orgSlug,
			{ kind: "run", runId: claim.runId },
			baseUrl,
		);
		return {
			action: "execute",
			run_id: claim.runId,
			...(eventRows[0] ? { event_id: Number(eventRows[0].id) } : {}),
			approval_url: approvalUrl,
			status: "pending_approval",
			message: `Operation '${operationName}' requires approval. Share the approval_url with the user to confirm.`,
		};
	}

	let row = {
		status: claim.status,
		action_output: claim.actionOutput,
		error_message: claim.errorMessage,
	};
	const deadline = Date.now() + 160_000;
	while (
		row.status === "pending" ||
		row.status === "claimed" ||
		row.status === "running"
	) {
		if (ctx.abortSignal?.aborted || Date.now() >= deadline) {
			return {
				action: "execute",
				run_id: claim.runId,
				status: "timeout",
				error_message: `Idempotent operation run ${claim.runId} is still in progress.`,
			};
		}
		await new Promise((resolve) => setTimeout(resolve, 500));
		const rows = await sql<{
			status: string;
			action_output: unknown;
			error_message: string | null;
		}>`
			SELECT status, action_output, error_message
			FROM runs
			WHERE organization_id = ${ctx.organizationId}
			  AND id = ${claim.runId}
			LIMIT 1
		`;
		if (!rows[0]) {
			return {
				action: "execute",
				run_id: claim.runId,
				status: "failed",
				error_message: `Idempotent operation run ${claim.runId} disappeared.`,
			};
		}
		row = rows[0];
	}

	if (row.status === "completed") {
		return {
			action: "execute",
			run_id: claim.runId,
			status: "completed",
			output: row.action_output ?? {},
		};
	}
	if (row.status === "timeout") {
		return {
			action: "execute",
			run_id: claim.runId,
			status: "timeout",
			error_message: row.error_message ?? `Run ${claim.runId} timed out.`,
		};
	}
	return {
		action: "execute",
		run_id: claim.runId,
		status: "failed",
		error_message:
			row.error_message ?? `Run ${claim.runId} ended with status '${row.status}'.`,
	};
}

async function handleExecute(
