# --- Local AI review gate ---------------------------------------------------
# Local-only: runs the deterministic suites in cwd, then invokes the reviewer
# from the model family opposite the current harness against
# `git diff <BASE>...HEAD` (BASE defaults to origin/main when available;
# override with BASE=<branch> env or `--base <branch>` arg). Prints a JSON
# verdict on the last line. If
# GitHub auth is available, posts a pi-review commit status; if the current
# branch has an open PR, also posts/updates a PR comment. See docs/REVIEW_SCHEMA.md.

review:
	@./scripts/review.sh $(if $(BASE),--base $(BASE),)

# Pre-review fixer: the reviewer CLI with WRITE access + the review rubrics,
# fixing review-grade findings (bugs, slop, stale claims) in the working tree
# BEFORE `make review` posts a status. Posts nothing, commits nothing —
# inspect its diff, commit, then run `make review` once on the settled HEAD.
review-fix:
	@./scripts/review-fix.sh $(if $(BASE),--base $(BASE),)

# Fast, deterministic CI gates that need NO database — the exact checks that
# `make review` (LLM-verdict only) does NOT run. Run this before opening/updating
# a PR so knip / typecheck / lint failures don't surface only in CI.
# NOT a substitute for the DB-backed suites (make test-integration) when you
# touch server/runtime code — but it catches the cheap, common misses.
pre-pr:
	@echo "🔎 [1/6] Build workspace packages (fresh dist)..."
	@# Typecheck resolves @lobu/* against built dist, not src. Without this a
	@# stale core dist yields PHANTOM errors on any contract change (e.g. a new
	@# field the dist predates) — the exact trap CI avoids by building first.
	@make build-packages
	@echo "🔎 [2/6] Strict typecheck (root + excluded packages)..."
	@bun run typecheck
	@for pkg in server connector-worker connector-sdk plugin-api plugin-host plugin-toolkit plugin-memory plugin-conversations plugin-media plugin-mcp embeddings cli; do \
		echo "   typecheck packages/$$pkg..."; \
		( cd "packages/$$pkg" && bunx tsc --noEmit ) || exit $$?; \
	done
	@echo "🔎 [3/6] Dead-code gate (knip --include files)..."
	@bun run knip --include files
	@echo "🔎 [4/6] Lint/format (biome)..."
	@bun run check
	@echo "🔎 [5/6] Exposed surface naming (no agent-facing 'watcher')..."
	@bun scripts/check-exposed-surface-naming.ts
	@echo "🔎 [6/6] Gateway LLM calls (no unapproved one-off clients)..."
	@node scripts/check-gateway-llm-calls.mjs
	@echo "✅ pre-pr gates clean. NOTE: confirm your fix is in 'git show HEAD:<file>',"
	@echo "   not just the working tree — a fix that isn't committed won't reach CI."
#!/usr/bin/env node
/**
 * Apply db/migrations/*.sql the way dbmate `up` does, with one important fix:
 * `transaction:false` sections run statement-at-a-time so CREATE/DROP INDEX
 * CONCURRENTLY is not trapped inside Postgres's implicit multi-statement
 * transaction (required when a heal DO precedes CONCURRENTLY in the same file).
 *
 * Records versions in public.schema_migrations (dbmate-compatible).
 *
 * Usage:
 *   DATABASE_URL=... node scripts/migrate-up.mjs
 *   MIGRATIONS_DIR=/app/db/migrations node scripts/migrate-up.mjs
 */
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import postgres from "postgres";

const migrationsDir =
  process.env.MIGRATIONS_DIR || join(process.cwd(), "db/migrations");
const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) {
  console.error("ERROR: DATABASE_URL not set");
  process.exit(1);
}

function listMigrationFiles(dir) {
  return readdirSync(dir)
    .filter((file) => file.endsWith(".sql"))
    .sort();
}

function parseTransactionOption(markerLine) {
  return !/\btransaction\s*:\s*false\b/i.test(markerLine);
}

function loadMigrationUp(dir, file) {
  const content = readFileSync(join(dir, file), "utf-8");
  const upMarker = content.match(/^--\s*migrate:up(.*)$/m);
  const transaction = parseTransactionOption(upMarker?.[0] ?? "-- migrate:up");
  const sql = content
    .split(/^--\s*migrate:down.*$/m)[0]
    .replace(/^--\s*migrate:up.*$/m, "")
    .replace(/^SET transaction_timeout = 0;\s*$/gm, "")
    .trim();
  return { sql, transaction };
}

/** Dollar-quote / string-literal aware statement splitter (see migration-loader.ts). */
function splitSqlStatements(sql) {
  const statements = [];
  let current = "";
  let i = 0;
  const n = sql.length;

  const pushCurrent = () => {
    const trimmed = current.trim();
    if (trimmed) statements.push(trimmed);
    current = "";
  };

  while (i < n) {
    const ch = sql[i];
    const next = sql[i + 1];

    if (ch === "-" && next === "-") {
      const end = sql.indexOf("\n", i);
      const chunk = end === -1 ? sql.slice(i) : sql.slice(i, end + 1);
      current += chunk;
      i += chunk.length;
      continue;
    }

    if (ch === "/" && next === "*") {
      const end = sql.indexOf("*/", i + 2);
      const chunk = end === -1 ? sql.slice(i) : sql.slice(i, end + 2);
      current += chunk;
      i += chunk.length;
      continue;
    }

    if (ch === "$") {
      const tagMatch = sql.slice(i).match(/^\$([A-Za-z_][A-Za-z0-9_]*)?\$/);
      if (tagMatch) {
        const tag = tagMatch[0];
        const close = sql.indexOf(tag, i + tag.length);
        if (close === -1) {
          current += sql.slice(i);
          break;
        }
        current += sql.slice(i, close + tag.length);
        i = close + tag.length;
        continue;
      }
    }

    if (ch === "'") {
      current += ch;
      i += 1;
      while (i < n) {
        current += sql[i];
        if (sql[i] === "'" && sql[i + 1] === "'") {
          current += sql[i + 1];
          i += 2;
          continue;
        }
        if (sql[i] === "'") {
          i += 1;
          break;
        }
        i += 1;
      }
      continue;
    }

    if (ch === ";") {
      pushCurrent();
      i += 1;
      continue;
    }

    current += ch;
    i += 1;
  }

  pushCurrent();
  return statements;
}

async function executeSection(sqlClient, section) {
  if (!section.sql.trim()) return;
  if (section.transaction) {
    await sqlClient.unsafe(section.sql);
    return;
  }
  for (const statement of splitSqlStatements(section.sql)) {
    await sqlClient.unsafe(statement);
  }
}

async function recordMigration(sqlClient, version) {
  await sqlClient.unsafe(
    `INSERT INTO public.schema_migrations (version) VALUES ($1) ON CONFLICT DO NOTHING`,
    [version]
  );
}

async function applyMigration(sqlClient, section, version) {
  if (section.transaction) {
    await sqlClient.begin(async (tx) => {
      await executeSection(tx, section);
      await recordMigration(tx, version);
    });
    return;
  }

  // CONCURRENTLY cannot share a transaction with the ledger write. These
  // migrations must therefore remain replay-safe, as dbmate also requires for
  // transaction:false migrations interrupted before their version is recorded.
  await executeSection(sqlClient, section);
  await recordMigration(sqlClient, version);
}

const sql = postgres(databaseUrl, { max: 1, onnotice: () => undefined });
let migrationLockHeld = false;

try {
  await sql.unsafe(`
    CREATE TABLE IF NOT EXISTS public.schema_migrations (
      version character varying(128) NOT NULL PRIMARY KEY
    )
  `);

  // start.sh runs on every replica. Serialize the ledger read + migration loop
  // on one Postgres session so two fresh pods cannot apply the same version.
  await sql.unsafe(`SELECT pg_advisory_lock(hashtext('lobu_migrate_up'))`);
  migrationLockHeld = true;

  const appliedRows = await sql.unsafe(
    `SELECT version FROM public.schema_migrations`
  );
  const applied = new Set(appliedRows.map((r) => r.version));

  for (const file of listMigrationFiles(migrationsDir)) {
    const version = file.split("_")[0] ?? "";
    if (applied.has(version)) continue;
    const up = loadMigrationUp(migrationsDir, file);
    if (!up.sql) continue;

    console.log(`Applying: ${file}`);
    await sql.unsafe("SET search_path TO public");
    await applyMigration(sql, up, version);
    console.log(`Applied: ${file}`);
  }

  console.log("Migrations complete");
} finally {
  if (migrationLockHeld) {
    await sql
      .unsafe(`SELECT pg_advisory_unlock(hashtext('lobu_migrate_up'))`)
      .catch(() => undefined);
  }
  await sql.end({ timeout: 1 }).catch(() => undefined);
}
