// Flattened schema for MCP compatibility (MCP doesn't support top-level unions)
export const ManageBehaviorsSchema = Type.Object(
  {
    action: Type.Union(
      [
        Type.Literal("create", {
          description:
            "Create a Behavior. Put the task statement in `prompt` and reusable know-how in `skills`; either satisfies the instruction requirement, and an event trigger with execution 'turn' may omit both.",
        }),
        Type.Literal("list", { description: "List Behaviors." }),
        Type.Literal("update", { description: "Patch Behavior config." }),
        Type.Literal("create_version", {
          description: "Create a new versioned Behavior config.",
        }),
        Type.Literal("complete_window", {
          description: "Submit a Behavior window result.",
        }),
        Type.Literal("trigger", {
          description: "Manually fire a Behavior run.",
        }),
        Type.Literal("delete", {
          description:
            "Archive one or more Behaviors (soft delete: status='archived', scheduling stops). Rows and versions are retained; no hard delete.",
        }),
        Type.Literal("set_reaction_script", {
          description: "Attach/remove a TypeScript reaction script.",
        }),
        Type.Literal("get_versions", {
          description: "List a Behavior\u2019s version history.",
        }),
        Type.Literal("get_version_details", {
          description: "Fetch full version config.",
        }),
        Type.Literal("get_component_reference", {
          description: "Static component/data-type documentation.",
        }),
        Type.Literal("submit_feedback", {
          description: "Submit per-field corrections on a window.",
        }),
        Type.Literal("get_feedback", {
          description: "Retrieve feedback for a Behavior.",
        }),
        Type.Literal("list_promoted", {
          description: "List entities promoted by a Behavior.",
        }),
        Type.Literal("create_from_version", {
          description: "Create Behaviors per entity from a template version.",
        }),
      ],
      { description: "Action to perform" }
    ),

    // Behavior identity (the persisted DB column is watcher_id)
    behavior_id: Type.Optional(
      Type.String({
        description:
          "[list/update/upgrade/get_versions/get_version_details/set_reaction_script/trigger] Behavior ID (numeric string)",
      })
    ),
    behavior_ids: Type.Optional(
      Type.Array(Type.String(), {
        description: "[delete] Array of Behavior IDs (numeric strings)",
      })
    ),

    // Fields for action="create"
    slug: Type.Optional(
      Type.String({ description: "[create] Unique Behavior identifier" })
    ),
    name: Type.Optional(
      Type.String({ description: "[create/create_version] Display name" })
    ),
    description: Type.Optional(
      Type.String({
        description: "[create/create_version] Behavior description",
      })
    ),
    entity_id: Type.Optional(
      Type.Number({
        description:
          "Entity ID. Optional for create — provide it to attach the Behavior to an entity; omit it for an org-scoped/global Behavior. Optional for list.",
      })
    ),
    entity_ids: Type.Optional(
      Type.Array(Type.Number(), {
        description:
          "[create_from_version] Array of entity IDs to create individual Behaviors for.",
      })
    ),
    version_id: Type.Optional(
      Type.Number({
        description:
          "[create_from_version] Source version ID to use as template for new Behaviors.",
      })
    ),
    name_pattern: Type.Optional(
      Type.String({
        description:
          '[create_from_version] Name pattern for created Behaviors. Use {{entity_name}} for substitution. Default: "{version_name}: {entity_name}".',
      })
    ),

    // Behavior config fields (create/create_version/update)
    prompt: Type.Optional(
      Type.String({
        description:
          "[create/create_version] Literal LLM instruction text for the Behavior — the task statement, frozen into the version. No template expansion happens: the text is delivered to the agent verbatim, and the window's data (content, sources, entities, extraction_schema) arrives alongside it in the knowledge-read payload. Reusable know-how belongs in `skills` instead, which is delivered as readable files rather than pasted in here. A schedule trigger, an event trigger with execution 'window', and a Behavior with no triggers each need an instruction source — supply `prompt`, `skills`, or both; an event trigger with execution 'turn' may omit both and use the built-in default.",
      })
    ),
    skills: Type.Optional(
      Type.Array(BehaviorSkillSchema, {
        maxItems: 5,
        description:
          "[create/create_version] Up to 5 ordered agent skills pinned into this version as {name, content} snapshots. Server-side agents receive `.skills/<name>/SKILL.md` files; device executors receive the same frozen text in their per-run task. Snapshots, not live references: editing the agent's library later does not change an existing version until a caller publishes a new one (`lobu apply` re-resolves on every run). FULL REPLACEMENT on create_version — passing it (even []) makes it the complete set, and OMITTING it keeps the stored snapshots unchanged. Every name must exist and be enabled in the owning agent's library, or the call is rejected rather than silently running under-instructed.",
      })
    ),
    sources: Type.Optional(
      Type.Array(SourceSchema, {
        description:
          "[create/create_version] Array of SQL data sources. Each source is { name, query }. To change them on an existing Behavior, publish a new version with action: 'create_version'. On create_version this array is the ONLY way to change them and is a FULL REPLACEMENT: passing it (even []) makes it the complete source set, [] clears everything, and OMITTING it keeps the stored sources unchanged. Instruction text is never an input: @-mention chips in an inherited prompt neither add nor remove sources. (On create only, chips in the prompt still seed the initial list, which is how the web composer authors them.) The response returns source_count and removed_sources so you can see what a replacement dropped.",
      })
    ),
    outputs: Type.Optional(
      Type.Union(
        [
          // Callers may pass a pre-serialized JSON string (parsed and
          // shape-checked by the server) or the object directly.
          Type.String(),
          BehaviorOutputsSchema,
          Type.Null(),
        ],
        {
          description:
            '[create/create_version] Named durable outputs for window execution. `{ entity, key, name? }` validates and upserts entities; `{ event }` appends standard event drafts. The object key is the top-level extracted_data array name. Event rows require content and may include title, metadata, author, source_url, occurred_at, parent_event_id, payload_type, and idempotency_key. Event triggers on a Behavior with outputs must use execution="window". Pass null on create_version to remove all declared outputs.',
        }
      )
    ),
    classifiers: Type.Optional(
      Type.Union(
        [
          // Callers may pass a pre-serialized JSON string (coerced by
          // parseJsonInput) or the array directly. Either way, the array shape
          // enforces `attribute_values` is a map, not an array (#2033 item 4).
          Type.String(),
          Type.Array(BehaviorClassifierDefinitionSchema),
        ],
        {
          description:
            "[create/create_version] Classifier definitions for extraction. Each attribute_values MUST be an object map keyed by value, never an array.",
        }
      )
    ),
    triggers: Type.Optional(
      Type.Array(BehaviorTriggerSchema, {
        minItems: 0,
        maxItems: 16,
        description:
          "[create/update/create_version] Canonical Behavior activations. Use a schedule trigger for cadence and timezone.",
      })
    ),
    agent_id: Type.Optional(
      Type.String({
        description:
          "[create/update] Agent ID that owns/executes this Behavior. [list] Optional owner filter.",
      })
    ),
    status: Type.Optional(
      Type.Union([Type.Literal("active"), Type.Literal("archived")], {
        description:
          "[list] Optional status filter. Omit to include active Behaviors only.",
      })
    ),
    include_details: Type.Optional(
      Type.Boolean({
        description:
          "[list] Include prompt, schema, and sources in the response (default: false).",
      })
    ),
    order_by: Type.Optional(
      Type.Union([Type.Literal("last_fired_at"), Type.Literal("created_at")], {
        description: "[list] Sort field (default: created_at).",
      })
    ),
    order_dir: Type.Optional(
      Type.Union([Type.Literal("asc"), Type.Literal("desc")], {
        description: "[list] Sort direction (default: desc).",
      })
    ),
    scheduler_client_id: Type.Optional(
      Type.Union([Type.String(), Type.Null()], {
        description:
          "[create/update/create_version] Optional MCP client ID that should auto-run this Behavior. Null clears it.",
      })
    ),
    device_worker_id: Type.Optional(
      Type.Union([Type.String(), Type.Null()], {
      context: true,
      query:
        "SELECT id, name, metadata FROM entities WHERE entity_type='person' AND deleted_at IS NULL AND (metadata ? 'x_handle' OR metadata ? 'linkedin_url' OR metadata ? 'company') ORDER BY updated_at DESC LIMIT 40",
    },
  },
  outputs: {
    signals: { event: "observation" },
    drafts: { event: "draft_reply" },
  },
  prompt:
    'Rank at most 8 new, high-signal X or LinkedIn posts for Burak. Use voice_profiles for taste and known_people for relationship context. Prefer AI, agents, infrastructure, developer tools, people he knows, launches, funding, and technical substance; ignore engagement bait, generic memes, and ads. Return each choice in `signals` as a standard observation event draft. Set `title` to the author/platform, `content` to the specific why plus a concrete suggested action, `source_url` to the source row source_url, `parent_event_id` to the source row id, and `idempotency_key` to its origin_id. Put `{ kind: "social_signal", platform, author, snippet, why, priority, source_origin_id, source_event_id, source_connection_id, suggested_action }` in metadata, copying the source id, origin_id, and connection_id exactly. Prefer posts not present in already_emitted. Also return `drafts`: either [] or exactly one standard draft_reply event for the single best item that genuinely deserves a response. Its content is only the proposed reply text; copy source_url and parent_event_id, use `draft:` plus origin_id as idempotency_key, and metadata `{ kind: "social_draft_reply", platform, author, why, priority, source_origin_id, source_event_id, source_connection_id }`. Never claim to publish: the reaction only stages the draft and the human submits it. Return empty arrays when nothing qualifies.',
  reactionsGuidance:
    "Declared outputs own event persistence and source-level deduplication. The reaction delivers a digest and stages at most one saved draft in the explicitly paired chrome-macbook browser; it never publishes.",
  reaction: reactionFromFile<typeof SocialInterestRadarReaction>(
    "./social-interest-radar.reaction.ts"
  ),
});

