  cmd: "sed -n '810,970p' packages/cli/src/commands/_lib/apply/apply-cmd.ts\nsed -n '880,1080p' packages/cli/src/commands/_lib/apply/client.ts\nrg -n \"--config|configPath|lobu.config.ts|LOBU_CONFIG\" packages/cli/src/commands packages/cli/src -g '*.ts' | head -120",
